#define BOUNDS_INIT_CAP 16
#define BOUNDS_VAR_INDEX_INIT_CAP 8u
#define BOUNDS_EXPR_INDEX_INIT_CAP 8u
#define BOUNDS_DIFFERENCE_INDEX_INIT_CAP 8u
#define BOUNDS_EXACT_INDEX_INIT_CAP 8u
